   * See https://github.com/cannatag/ldap3/blob/4d33166f0869b929f59c6e6825a1b9505eb99967/ldap3/utils/conv.py#L91
   */
  private class LdapEscapeFilterCall extends DataFlow::CallCfgNode, Escaping::Range {
