    private predicate classEscapeMatches(string clazz, string char) {
      clazz = "d" and
      char = "0123456789".charAt(_)
      or
      clazz = "s" and
      char = [" ", "\t", "\r", "\n", 11.toUnicode(), 12.toUnicode()] // 11.toUnicode() = \v, 12.toUnicode() = \f
