  /**
   * A call to `xmltodict.parse`.
   */
  private class XMLtoDictParsing extends API::CallNode, XML::XmlParsing::Range {
    XMLtoDictParsing() { this = API::moduleImport("xmltodict").getMember("parse").getACall() }

