/**
 * Provides classes modeling security-relevant aspects of the `pydantic` PyPI package.
 *
 * See
 * - https://pypi.org/project/pydantic/
 * - https://pydantic-docs.helpmanual.io/
 */

private import python
private import semmle.python.dataflow.new.DataFlow
private import semmle.python.dataflow.new.TaintTracking
private import semmle.python.Concepts
private import semmle.python.ApiGraphs
private import semmle.python.frameworks.data.ModelsAsData

/**
 * INTERNAL: Do not use.
 *
 * Provides models for `pydantic` PyPI package.
 *
 * See
 * - https://pypi.org/project/pydantic/
 * - https://pydantic-docs.helpmanual.io/
 */
module Pydantic {
  /**
   * Provides models for `pydantic.BaseModel` subclasses (a pydantic model).
   *
   * See https://pydantic-docs.helpmanual.io/usage/models/.
   */
  module BaseModel {
    /** Gets a reference to a `pydantic.BaseModel` subclass (a pydantic model). */
    API::Node subclassRef() {
      result = API::moduleImport("pydantic").getMember("BaseModel").getASubclass+()
      or
      result = ModelOutput::getATypeNode("pydantic.BaseModel~Subclass").getASubclass*()
    }

    /**
     * A source of instances of `pydantic.BaseModel` subclasses, extend this class to model new instances.
     *
     * This can include instantiations of the class, return values from function
     * calls, or a special parameter that will be set when functions are called by an external
     * library.
     *
     * Use the predicate `BaseModel::instance()` to get references to instances of `pydantic.BaseModel`.
     */
    abstract class InstanceSource extends DataFlow::LocalSourceNode { }

    /** Gets a reference to an instance of a `pydantic.BaseModel` subclass. */
    private DataFlow::TypeTrackingNode instance(DataFlow::TypeTracker t) {
      t.start() and
      result instanceof InstanceSource
      or
      t.start() and
      instanceStepToPydanticModel(_, result)
      or
      exists(DataFlow::TypeTracker t2 | result = instance(t2).track(t2, t))
    }

    /** Gets a reference to an instance of a `pydantic.BaseModel` subclass. */
    DataFlow::Node instance() { instance(DataFlow::TypeTracker::end()).flowsTo(result) }

    /**
     * A step from an instance of a `pydantic.BaseModel` subclass, that might result in
     * an instance of a `pydantic.BaseModel` subclass.
     *
     * NOTE: We currently overapproximate, and treat all attributes as containing
     * another pydantic model. For the code below, we _could_ limit this to `main_foo`
     * and members of `other_foos`. IF THIS IS CHANGED, YOU MUST CHANGE THE ADDITIONAL
     * TAINT STEPS BELOW, SUCH THAT SIMPLE ACCESS OF SOMETHING LIKE `str` IS STILL
     * TAINTED.
     *
     *
     * ```py
     * class MyComplexModel(BaseModel):
     * field: str
     * main_foo: Foo
     * other_foos: List[Foo]
     * ```
     */
    private predicate instanceStepToPydanticModel(DataFlow::Node nodeFrom, DataFlow::Node nodeTo) {
      // attributes (such as `model.foo`)
      nodeFrom = instance() and
      nodeTo.(DataFlow::AttrRead).getObject() = nodeFrom
      or
      // subscripts on attributes (such as `model.foo[0]`). This needs to handle nested
      // lists (such as `model.foo[0][0]`), and access being split into multiple
      // statements (such as `xs = model.foo; xs[0]`).
      //
      // To handle this we overapproximate which things are a Pydantic model, by
      // treating any subscript on anything that originates on a Pydantic model to also
      // be a Pydantic model. So `model[0]` will be an overapproximation, but should not
      // really cause problems (since we don't expect real code to contain such accesses)
      nodeFrom = instance() and
      nodeTo.asCfgNode().(SubscriptNode).getObject() = nodeFrom.asCfgNode()
    }

    /**
     * Extra taint propagation for `pydantic.BaseModel` subclasses. (note that these could also be `pydantic.BaseModel` subclasses)
     */
    private class AdditionalTaintStep extends TaintTracking::AdditionalTaintStep {
      override predicate step(DataFlow::Node nodeFrom, DataFlow::Node nodeTo) {
        // NOTE: if `instanceStepToPydanticModel` is changed to be more precise, these
        // taint steps should be expanded, such that a field that has type `str` is
        // still tainted.
        instanceStepToPydanticModel(nodeFrom, nodeTo)
      }
    }
  }
}

/**
 * Provides default sources, sinks and sanitizers for detecting
 * "path injection"
 * vulnerabilities, as well as extension points for adding your own.
 */

private import python
private import semmle.python.dataflow.new.DataFlow
private import semmle.python.Concepts
private import semmle.python.dataflow.new.RemoteFlowSources
private import semmle.python.dataflow.new.BarrierGuards

/**
 * Provides default sources, and sinks for detecting
 * "path injection"
 * vulnerabilities, as well as extension points for adding your own.
 *
 * Since the path-injection configuration setup is rather complicated, we do not
 * expose a `Sanitizer` class, and instead you should extend
 * `Path::PathNormalization::Range` and `Path::SafeAccessCheck::Range` from
 * `semmle.python.Concepts` instead.
 */
module PathInjection {
  /**
   * A data flow source for "path injection" vulnerabilities.
   */
  abstract class Source extends DataFlow::Node { }

  /**
   * A data flow sink for "path injection" vulnerabilities.
   * Such as a file system access.
   */
  abstract class Sink extends DataFlow::Node { }

  /**
   * A sanitizer for "path injection" vulnerabilities.
   *
   * This should only be used for things like calls to library functions that perform their own
   * (correct) normalization/escaping of untrusted paths.
   *
   * Please also see `Path::SafeAccessCheck` and `Path::PathNormalization` Concepts.
   */
  abstract class Sanitizer extends DataFlow::Node { }

  /**
   * DEPRECATED: Use `ActiveThreatModelSource` from Concepts instead!
   */
  deprecated class RemoteFlowSourceAsSource = ActiveThreatModelSourceAsSource;

  /**
   * An active threat-model source, considered as a flow source.
   */
  private class ActiveThreatModelSourceAsSource extends Source, ActiveThreatModelSource { }

  /**
   * A file system access, considered as a flow sink.
   */
  class FileSystemAccessAsSink extends Sink {
    FileSystemAccessAsSink() {
      this = any(FileSystemAccess e).getAPathArgument() and
      // since implementation of Path.open in pathlib.py is like
      // ```py
      // def open(self, ...):
      //     return io.open(self, ...)
      // ```
      // any time we would report flow to the `path_obj.open` sink, we can ALSO report
      // the flow from the `self` parameter to the `io.open` sink -- obviously we
      // don't want that.
      //
      // However, simply removing taint edges out of a sink is not a good enough solution,
      // since we would only flag one of the `p.open` calls in the following example
      // due to use-use flow
      // ```py
      // p.open()
      // p.open()
      // ```
      //
      // The same approach is used in the command injection query.
      not exists(Module inStdlib |
        inStdlib.getName() in ["pathlib", "os"] and
        this.getScope().getEnclosingModule() = inStdlib and
        // do allow this call if we're analyzing, say, pathlib.py as part of CPython though
        not exists(inStdlib.getFile().getRelativePath())
      )
    }
  }

  private import semmle.python.frameworks.data.ModelsAsData

  private class DataAsFileSink extends Sink {
    DataAsFileSink() { this = ModelOutput::getASinkNode("path-injection").asSink() }
  }

  /**
   * A comparison with a constant, considered as a sanitizer-guard.
   */
  class ConstCompareAsSanitizerGuard extends Sanitizer, ConstCompareBarrier { }

  /** DEPRECATED: Use ConstCompareAsSanitizerGuard instead. */
  deprecated class StringConstCompareAsSanitizerGuard = ConstCompareAsSanitizerGuard;
}

/**
 * Provides default sources, sinks and sanitizers for detecting
 * "URL redirection"
 * vulnerabilities, as well as extension points for adding your own.
 */

private import python
private import semmle.python.dataflow.new.DataFlow
private import semmle.python.Concepts
private import semmle.python.dataflow.new.RemoteFlowSources
private import semmle.python.dataflow.new.BarrierGuards
private import semmle.python.frameworks.data.ModelsAsData

/**
 * Provides default sources, sinks and sanitizers for detecting
 * "URL redirection"
 * vulnerabilities, as well as extension points for adding your own.
 */
module UrlRedirect {
  /**
   * A state value to track whether the untrusted data may contain backslashes.
   */
  abstract class FlowState extends string {
    bindingset[this]
    FlowState() { any() }
  }

  /**
   * A state value signifying that the untrusted data may contain backslashes.
   */
  class MayContainBackslashes extends UrlRedirect::FlowState {
    MayContainBackslashes() { this = "MayContainBackslashes" }
  }

  /**
   * A state value signifying that any backslashes in the untrusted data have
   * been eliminated, but no other sanitization has happened.
   */
  class NoBackslashes extends UrlRedirect::FlowState {
    NoBackslashes() { this = "NoBackslashes" }
  }

  /**
   * A data flow source for "URL redirection" vulnerabilities.
   */
  abstract class Source extends DataFlow::Node { }

  /**
   * A data flow sink for "URL redirection" vulnerabilities.
   */
  abstract class Sink extends DataFlow::Node { }

  /**
   * A sanitizer for "URL redirection" vulnerabilities.
   */
  abstract class Sanitizer extends DataFlow::Node {
    /**
     * Holds if this sanitizer sanitizes flow in the given state.
     */
    abstract predicate sanitizes(FlowState state);
  }

  /**
   * An additional flow step for "URL redirection" vulnerabilities.
   */
  abstract class AdditionalFlowStep extends DataFlow::Node {
    /**
     * Holds if there should be an additional flow step from `nodeFrom` in `stateFrom`
     * to `nodeTo` in `stateTo`.
     *
     * For example, a call to `replace` that replaces backslashes with forward slashes
     * takes flow from `MayContainBackslashes` to `NoBackslashes`.
     */
    abstract predicate step(
      DataFlow::Node nodeFrom, FlowState stateFrom, DataFlow::Node nodeTo, FlowState stateTo
    );
  }

  /**
   * DEPRECATED: Use `ActiveThreatModelSource` from Concepts instead!
   */
  deprecated class RemoteFlowSourceAsSource = ActiveThreatModelSourceAsSource;

  /**
   * An active threat-model source, considered as a flow source.
   */
  private class ActiveThreatModelSourceAsSource extends Source, ActiveThreatModelSource { }

  /**
   * A HTTP redirect response, considered as a flow sink.
   */
  class RedirectLocationAsSink extends Sink {
    RedirectLocationAsSink() {
      this = any(Http::Server::HttpRedirectResponse e).getRedirectLocation()
    }
  }

  private class SinkFromModel extends Sink {
    SinkFromModel() { this = ModelOutput::getASinkNode("url-redirection").asSink() }
  }

  /**
   * The right side of a string-concat, considered as a sanitizer.
   */
  class StringConcatAsSanitizer extends Sanitizer {
    StringConcatAsSanitizer() {
      // Url redirection is a problem only if the user controls the prefix of the URL.
      // TODO: This is a copy of the taint-sanitizer from the old points-to query, which doesn't
      // cover formatting.
      exists(BinaryExprNode string_concat | string_concat.getOp() instanceof Add |
        string_concat.getRight() = this.asCfgNode()
      )
    }

    override predicate sanitizes(FlowState state) {
      // sanitize all flow states
      any()
    }
  }

  /**
   * A call that replaces backslashes with forward slashes or eliminates them
   * altogether, considered as a partial sanitizer, as well as an additional
   * flow step.
   */
  class ReplaceBackslashesSanitizer extends Sanitizer, AdditionalFlowStep, DataFlow::MethodCallNode {
    DataFlow::Node receiver;

    ReplaceBackslashesSanitizer() {
      this.calls(receiver, "replace") and
      this.getArg(0).asExpr().(StringLiteral).getText() = "\\" and
      this.getArg(1).asExpr().(StringLiteral).getText() in ["/", ""]
    }

    override predicate sanitizes(FlowState state) { state instanceof MayContainBackslashes }

    override predicate step(
      DataFlow::Node nodeFrom, FlowState stateFrom, DataFlow::Node nodeTo, FlowState stateTo
    ) {
      nodeFrom = receiver and
      stateFrom instanceof MayContainBackslashes and
      nodeTo = this and
      stateTo instanceof NoBackslashes
    }
  }

  /**
   * A comparison with a constant, considered as a sanitizer-guard.
   */
  class ConstCompareAsSanitizerGuard extends Sanitizer, ConstCompareBarrier {
    override predicate sanitizes(FlowState state) {
      // sanitize all flow states
      any()
    }
  }

  /** DEPRECATED: Use ConstCompareAsSanitizerGuard instead. */
  deprecated class StringConstCompareAsSanitizerGuard = ConstCompareAsSanitizerGuard;
}

