      HeadersAppend() {
        exists(DataFlow::AttrRead headers |
          headers.accesses(instance(), "headers") and
          this.calls(headers, "append")
        )
      }

      override DataFlow::Node getNameArg() { result = [this.getArg(0), this.getArgByName("key")] }

