        this =
          [
            etreeRef().getMember("XMLParser").getAnInstance(),
            etreeRef().getMember("get_default_parser").getReturn()
          ].getMember("close").getReturn()
        or
        // TODO: `XMLID`, `XMLDTDID`, `parseid` returns a tuple of which the first element is an `Element`.
